import hashlib

from ffadv4manager.core.inspect_file import inspect_file


def test_inspects_size_hash_and_known_gcode_comments(tmp_path):
    payload = (
        "; generated by OrcaSlicer 2.0\n"
        "; layer_height = 0.2\n"
        "; nozzle_diameter = 0.4\n"
        "; filament_type = PLA\n"
        "; estimated printing time (normal mode) = 1h 2m\n"
        "G28\n"
    ).encode()
    path = tmp_path / "part.gcode"
    path.write_bytes(payload)

    result = inspect_file(path)

    assert result.path == path
    assert result.size_bytes == len(payload)
    assert result.sha256 == hashlib.sha256(payload).hexdigest()
    assert result.format == "gcode"
    assert result.metadata == {
        "slicer": "OrcaSlicer 2.0",
        "layer_height": "0.2",
        "nozzle_diameter": "0.4",
        "filament_type": "PLA",
        "estimated_print_time": "1h 2m",
    }


def test_gx_is_not_decoded_or_scanned_as_text(tmp_path):
    payload = b"\x00\xff; generated by FakeSlicer\nlayer_height = 0.2"
    path = tmp_path / "part.gx"
    path.write_bytes(payload)

    result = inspect_file(path)

    assert result.size_bytes == len(payload)
    assert result.sha256 == hashlib.sha256(payload).hexdigest()
    assert result.format == "gx"
    assert result.metadata == {}


def test_unrecognized_or_binary_gcode_has_no_metadata(tmp_path):
    path = tmp_path / "opaque.gcode"
    path.write_bytes(b"\x00; generated by FakeSlicer\n")

    assert inspect_file(path).metadata == {}


def test_unknown_extension_reports_basic_file_info_only(tmp_path):
    path = tmp_path / "payload.bin"
    path.write_bytes(b"; generated by FakeSlicer\n")

    result = inspect_file(path)

    assert result.format == "unknown"
    assert result.metadata == {}
